const storage={get:(k)=>{try{return localStorage.getItem(k)}catch{return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch{}}};
const validTable=x=>/^(T(?:0?[1-9]|[1-9][0-9])|TAKEAWAY)$/i.test(String(x||''));
const params=new URLSearchParams(location.search),rawTable=params.get('table');
let state={table:rawTable&&validTable(rawTable)?rawTable.toUpperCase():(!rawTable&&validTable(storage.get('lotus-qr-table'))?storage.get('lotus-qr-table'):''),badTable:Boolean(rawTable&&!validTable(rawTable)),catalog:fallback,accepting:false,serverOnline:false,view:'menu',category:'all',search:'',cart:[],modal:null,lastOrder:null,demoPreview:false,submitting:false,statusLoading:false,toast:'',orderNote:'',tablePicker:false,pendingTable:'',uncertain:false,member:null,loyaltyTransactions:[],vouchers:[],voucherCode:'',appliedVoucher:null,voucherBusy:false,authMode:'login',authBusy:false,receiptImage:'',receiptBusy:false,memberReturnView:'member',servicePending:false,paymentChoice:'BANK'};
let statusTimer=0,toastTimer=0,catalogRefreshing=false;
const t=key=>`${translations.vi[key]||key} / ${translations.zh[key]||key}`;
const bi=key=>`<span class="bi"><span class="bi-vi" lang="vi">${esc(translations.vi[key]||key)}</span><span class="bi-zh" lang="zh-CN">${esc(translations.zh[key]||key)}</span></span>`;
const names=p=>`<span class="bi"><span class="bi-vi" lang="vi">${esc(p.name)}</span><span class="bi-zh" lang="zh-CN">${esc(p.nameCn||p.name)}</span></span>`;
const tableText=table=>table==='TAKEAWAY'?bi('takeaway'):`${bi('table')} <strong>${esc(table)}</strong>`;
const fmt=value=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(value)+'đ';
const esc=value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const orderSteps=['NEW','ACCEPTED','PREPARING','READY','SERVED','PAID'];
const stepName={NEW:'orderNew',ACCEPTED:'accepted',PREPARING:'preparing',READY:'ready',SERVED:'served',PAID:'paid'};
const getProduct=id=>state.catalog.products.find(p=>p.id===String(id));
const getCartKey=(id,mods)=>String(id)+'|'+JSON.stringify([mods.size,mods.spice,mods.note]);
const cartKey=()=>`lotus-qr-cart:${state.table||'no-table'}`;
function loadCart(){try{const c=JSON.parse(storage.get(cartKey())||'[]');state.cart=Array.isArray(c)?c.filter(x=>x&&typeof x.productId==='string'&&Number.isInteger(x.qty)&&x.qty>0).slice(0,30):[]}catch{state.cart=[]}state.orderNote=storage.get(cartKey()+':note')||''}
function saveCart(){storage.set(cartKey(),JSON.stringify(state.cart));storage.set(cartKey()+':note',state.orderNote)}
function total(){return state.cart.reduce((a,x)=>a+x.qty*x.price,0)}
function count(){return state.cart.reduce((a,x)=>a+x.qty,0)}
function isReady(){return state.accepting&&state.serverOnline&&navigator.onLine!==false&&state.cart.every(x=>{const p=getProduct(x.productId);return p?.active&&p.available})}
function toast(message){state.toast=message;const old=$('.toast');if(old)old.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');const pair=String(message).split(' / ');if(pair.length===2){for(const [idx,part] of pair.entries()){const span=document.createElement('span');span.lang=idx?'zh-CN':'vi';span.textContent=part;el.appendChild(span)}}else el.textContent=message;document.body.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500)}
function productImage(p){return `<div class="art" aria-hidden="true"><span class="sku">${esc(p.sku)}</span><span class="emoji">${esc(p.icon||'🍽️')}</span></div>`}
function header(){return `<header class="head"><div class="head-row">${state.catalog.store.logo?'<img class="mark" src="/api/store/logo" alt="Logo cửa tiệm" style="object-fit:contain">':'<span class="mark" aria-hidden="true">發</span>'}<div class="head-brand"><strong lang="vi">${esc(state.catalog.store.name)}</strong><small lang="zh-CN">${esc(state.catalog.store.nameCn||'发财烧腊')}</small></div><button class="table-pill" data-action="table" aria-label="${t('selectTable')}">${state.table?tableText(state.table):bi('tableMissing')} <span aria-hidden="true">▾</span></button></div></header>`}
function footer(){const tabs=[['menu','⌂','menu'],['cart','▤','cart'],['orders','◷','orders'],['member','♙','member']];return `<nav class="bottom" aria-label="Navigation">${tabs.map(([view,glyph,key])=>`<button type="button" data-view="${view}" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}><span class="glyph">${glyph}</span>${bi(key)}${view==='cart'&&count()?' ('+count()+')':''}</button>`).join('')}</nav>`}
function banner(){if(navigator.onLine===false)return `<div class="notice red" role="alert">${bi('offline')}</div>`;if(!state.accepting)return `<div class="notice" role="status">${bi('outage')}</div>`;return ''}
function hero(){return `<div class="hero"><div class="eyebrow">${bi('tag')}</div><h1>${esc(state.catalog.store.name)}</h1><p>${bi('tagline')}</p><div class="hero-meta"><span>◉ ${state.table?tableText(state.table):bi('tableMissing')}</span><span>${isReady()?'● '+bi('online'):'○ '+bi('preview')}</span></div></div>`}
function cats(){const values=[['all',bi('all')],...new Set(state.catalog.products.filter(p=>p.active).map(p=>p.category))].map(x=>Array.isArray(x)?x:[x,x==='Cơm phần'?bi('rice'):x==='Canh'?bi('soup'):esc(x)]);return `<div class="cats" role="group" aria-label="Categories">${values.map(([id,label])=>`<button class="chip ${state.category===id?'active':''}" data-cat="${esc(id)}" aria-pressed="${state.category===id}">${label}</button>`).join('')}</div>`}
function productList(){let products=state.catalog.products.filter(x=>x.active&&(!state.category||state.category==='all'||x.category===state.category));if(state.search.trim()){const q=state.search.trim().toLowerCase();products=products.filter(p=>(p.name+' '+p.nameCn+' '+p.sku).toLowerCase().includes(q))}return products.length?`<div class="products">${products.map(p=>`<article class="product">${productImage(p)}<div class="product-body"><h3 lang="vi">${esc(p.name)}</h3><span class="cn" lang="zh-CN">${esc(p.nameCn||p.name)}</span><div class="product-footer"><span class="price">${p.price!==p.largePrice?`<span class="from-label">${bi('from')}</span>`:''}<span class="amount">${fmt(p.price)}</span></span>${p.available?`<button class="add" data-add="${esc(p.id)}" aria-label="${t('choose')} ${esc(p.name)} ${esc(p.nameCn||p.name)}">+</button>`:`<span class="sold-out">${bi('soldOut')}</span>`}</div></div></article>`).join('')}</div>`:`<div class="empty">${bi('emptySearch')}</div>`}
function menu(){return `<div id="menu-hero">${hero()}</div><div id="menu-connect">${banner()}</div><main class="section"><div class="section-heading"><h2>${bi('menu')}</h2><span>${state.catalog.products.filter(p=>p.active).length} ${bi('count')}</span></div><label for="search" class="search-label">${bi('find')}</label><input id="search" class="search" type="search" autocomplete="off" placeholder="${esc(translations.vi.find)}" value="${esc(state.search)}">${cats()}<div id="product-list">${productList()}</div></main>`}
function cartLine(x,index){const p=getProduct(x.productId);if(!p)return `<article class="cart-line"><strong>${esc(x.productId)} · Món không còn trên thực đơn</strong><button data-remove="${index}">Xóa khỏi giỏ</button></article>`;const size=x.mods.size==='大'?'large':'regular';const spiceKey=({不辣:'none',小:'mild',中:'medium',大:'hot'})[x.mods.spice];return `<article class="cart-line"><span class="cart-art">${esc(p.icon||'🍽️')}</span><div class="cart-info"><strong>${names(p)}</strong><small>${p.size?bi(size):esc(p.sizeLabel||'')}${p.spicy&&spiceKey?' · '+bi(spiceKey):''}${x.mods.note?' · '+esc(x.mods.note):''}${optionLabels(x.mods,p)?' · '+esc(optionLabels(x.mods,p)):''}</small><div class="cart-actions"><div class="qty"><button data-qty="${index}" data-delta="-1" aria-label="Giảm số lượng / 减少数量">−</button><span>${x.qty}</span><button data-qty="${index}" data-delta="1" aria-label="Tăng số lượng / 增加数量">+</button></div><strong class="price">${fmt(x.price*x.qty)}</strong></div><div class="row"><button class="ghost" data-edit="${index}">${bi('edit')}</button><button class="ghost" data-remove="${index}">${bi('delete')}</button></div></div></article>`}
function voucherPanel(){return `<section class="panel voucher-panel" aria-label="${t('voucher')}"><div class="section-heading"><h2>${bi('voucher')}</h2>${state.member?`<span class="status">${bi('signedIn')}</span>`:''}</div><p class="sub">${bi('voucherHint')}</p><div class="voucher-controls"><input id="voucher-input" type="text" maxlength="32" autocomplete="off" spellcheck="false" placeholder="${esc(translations.vi.voucherPlaceholder)}" value="${esc(state.voucherCode)}" aria-label="${t('voucher')}"><button class="secondary" data-action="apply-voucher" ${state.voucherBusy||state.uncertain?'disabled':''}>${bi('apply')}</button></div>${state.appliedVoucher?`<div class="voucher-ok"><strong>${bi('voucherApplied')}: ${esc(state.appliedVoucher.voucher.code)}</strong><span>− ${fmt(state.appliedVoucher.discount)}</span><button class="ghost" data-action="remove-voucher">${bi('removeVoucher')}</button></div>`:''}${state.vouchers.length?`<div class="voucher-offers"><strong>${bi('voucherList')}</strong>${state.vouchers.map(v=>`<button type="button" class="offer" data-offer="${esc(v.code)}"><span>${esc(v.titleVi)}<small lang="zh-CN">${esc(v.titleZh)}</small><small>${bi('minSpend')}: ${fmt(v.minSpend)}</small></span><strong>${esc(v.code)}</strong></button>`).join('')}</div>`:''}</section>`}
function memberPrompt(){return `<section class="panel member-prompt">${state.member?`<strong>${bi('signedIn')}: ${esc(state.member.displayName)}</strong><p class="sub">${esc(state.member.tier)} · ${Number(state.member.points)||0} điểm / 积分</p>`:`<strong>${bi('member')}</strong><p class="sub">${bi('memberPrompt')}</p><button class="secondary" data-action="member-from-cart">${bi('login')} / ${bi('register')}</button><p class="sub" style="margin-top:8px">${bi('guestContinue')}</p>`}</section>`}
function memberView(){return `<main class="section member-page"><h1 class="page-title">${bi('memberTitle')}</h1>${state.member?`<section class="panel"><div class="profile-box"><img class="mark" src="/api/store/logo" alt="Logo Echo Coffee"><div><strong>${esc(state.member.displayName)}</strong><div class="sub">${esc(state.member.phone)}</div></div></div><h2>${esc(state.member.tier)} · ${Number(state.member.points)||0} điểm / 积分</h2><p class="sub">${bi('memberInfo')}</p><p class="sub">Tổng chi ${fmt(state.member.spend)} · ${Number(state.member.orders)||0} đơn đã thanh toán / 已付款订单</p><h3>Lịch sử tích điểm / 积分记录</h3>${state.loyaltyTransactions.map(x=>`<p class="sub">${esc(x.orderCode)} · ${fmt(x.amount)} → +${Number(x.points)} điểm · ${esc(new Date(x.paidAt).toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}))}</p>`).join('')||'<p class="sub">Chưa có giao dịch được xác nhận / 暂无积分记录</p>'}<button class="secondary" data-action="refresh-loyalty">Cập nhật điểm / 刷新积分</button><form id="change-password-form" class="password-change"><h3>Đổi mật khẩu / 修改密码</h3><div class="field"><label>Mật khẩu hiện tại / 旧密码</label><input name="currentPassword" type="password" required autocomplete="current-password"></div><div class="field"><label>Mật khẩu mới (1–11 ký tự) / 新密码</label><input name="newPassword" type="password" minlength="1" maxlength="11" required autocomplete="new-password"></div><button class="secondary" type="submit">Lưu mật khẩu / 保存密码</button></form> <button class="secondary" data-action="logout" ${state.authBusy?'disabled':''}>${bi('logout')}</button></section>`:`<section class="panel"><div class="auth-switch"><button type="button" class="${state.authMode==='login'?'selected':''}" data-auth-mode="login">${bi('login')}</button><button type="button" class="${state.authMode==='register'?'selected':''}" data-auth-mode="register">${bi('register')}</button></div><form id="member-form" autocomplete="on">${state.authMode==='register'?`<div class="field"><label for="member-name">${bi('name')}</label><input id="member-name" name="name" required minlength="2" maxlength="80" autocomplete="name" placeholder="Nguyễn Văn A"></div>`:''}<div class="field"><label for="member-phone">${bi('phone')}</label><input id="member-phone" name="phone" required inputmode="tel" type="tel" autocomplete="tel" placeholder="0xxxxxxxxx (10–11 số)" minlength="10" maxlength="11" pattern="0[0-9]{9,10}"></div>${state.authMode==='login'?`<div class="field"><label for="member-password">${bi('password')}</label><input id="member-password" name="password" required type="password" maxlength="128" autocomplete="current-password"></div>`:`<p class="sub">Mật khẩu ban đầu là số điện thoại đã đăng ký. Hãy đổi mật khẩu sau khi đăng ký.<br>初始密码为手机号，注册后请修改密码。</p>`}<button type="submit" class="primary" ${state.authBusy?'disabled':''}>${state.authBusy?bi('authWait'):bi(state.authMode)}</button></form><p class="sub" style="margin-top:16px">${bi('guestContinue')}</p></section>`}<section class="panel" style="margin-top:12px"><h2>${bi('seeGuide')}</h2><p>${bi('guide1')}</p><p>${bi('guide2')}</p><p>${bi('guide3')}</p><p>${bi('guide4')}</p><p class="sub">${bi('receiptNote')}</p></section></main>`}
function estimatedTax(){const base=Math.max(0,total()-(state.appliedVoucher?.discount||0));const rate=state.catalog.store.taxRate||0;return state.catalog.store.taxMode==='EXCLUSIVE'?Math.round(base*rate/10000):Math.round(base*rate/(10000+rate))}
function discountedTotal(){return Math.max(0,total()-(state.appliedVoucher?.discount||0))+(state.catalog.store.taxMode==='EXCLUSIVE'?estimatedTax():0)}
function clearVoucher(){state.appliedVoucher=null;state.voucherCode=''}
function cart(){return `<main class="section"><h1 class="page-title">${bi('cartTitle')}</h1><p class="sub">${bi('cartSub')}</p><div id="cart-connect">${banner()}</div>${state.cart.length?`<div class="cart-list" style="margin-top:16px">${state.cart.map(cartLine).join('')}</div><div class="field"><label for="order-note">${bi('orderNote')}</label><textarea id="order-note" maxlength="300" rows="3" placeholder="${esc(translations.vi.orderNotePlaceholder)}">${esc(state.orderNote)}</textarea></div>${memberPrompt()}${voucherPanel()}<div class="summary"><div class="sum-row"><span>${bi('subtotal')} · ${count()} ${bi('count')}</span><strong>${fmt(total())}</strong></div>${state.appliedVoucher?`<div class="sum-row"><span>${bi('discount')} · ${esc(state.appliedVoucher.voucher.code)}</span><strong>−${fmt(state.appliedVoucher.discount)}</strong></div>`:''}${estimatedTax()?`<div class="sum-row"><span>${state.catalog.store.taxMode==='EXCLUSIVE'?'Thuế cộng thêm':'Thuế đã gồm'} · 税</span><strong>${fmt(estimatedTax())}</strong></div>`:''}<div class="sum-row total"><span>${bi('total')}</span><span>${fmt(discountedTotal())}</span></div></div><div class="field"><label>Chọn cách thanh toán · 选择付款方式</label><div class="option-group" role="group" aria-label="Phương thức thanh toán"><button type="button" class="option ${state.paymentChoice==='BANK'?'selected':''}" data-payment-choice="BANK" aria-pressed="${state.paymentChoice==='BANK'}">Chuyển khoản · 转账</button><button type="button" class="option ${state.paymentChoice==='CASH'?'selected':''}" data-payment-choice="CASH" aria-pressed="${state.paymentChoice==='CASH'}">Tiền mặt · 现金</button></div></div><div class="pay-hint">ⓘ ${bi('payLater')}<br><small>${bi('notePreview')}</small></div>${!isReady()?`<p class="sub" style="margin-top:10px;text-align:center">${bi('demoBadge')}</p>`:''}`:`<div class="empty">${bi('emptyCart')}<p><button class="secondary" data-view="menu">${bi('browse')}</button></p></div>`}</main>`}
function paymentQrSvg(value){if(typeof LotusQRCode!=='function')return '';const qr=new LotusQRCode(-1,1);qr.addData(value);qr.make();const n=qr.getModuleCount(),pad=4;let path='';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))path+=`M${x+pad} ${y+pad}h1v1h-1z`;return `<svg id="payment-qr-svg" viewBox="0 0 ${n+pad*2} ${n+pad*2}" width="240" height="240" aria-label="QR ngân hàng"><rect width="100%" height="100%" fill="white"/><path d="${path}" fill="black"/></svg>`}
function bankCard(o){if(o.paymentStatus==='PAID')return `<div class="notice">Đã thanh toán · 已付款${o.refundedAmount?`<br>Đã hoàn: ${fmt(o.refundedAmount)} · 已退款`:''}</div>`;const p=o.bankPayment;if(o.status==='SPLIT')return `<div class="notice">Đơn đã tách bill. Vui lòng thanh toán từng bill với nhân viên.<br>订单已分单，请向店员分别结账。</div>`;if(o.paymentPreference==='CASH')return `<div class="notice">Bạn đã chọn tiền mặt. Nhân viên sẽ đến bàn ${esc(o.table)} để thu tiền và xác nhận thanh toán.<br>您已选择现金付款，店员会到桌边收款。</div>`;if(!p)return `<div class="notice">Thanh toán tiền mặt với nhân viên. QR ngân hàng chưa được cửa hàng cấu hình.<br>请向店员付现金；银行账户尚未设置。</div>`;return `<div class="payment-card" style="padding:18px;border:1px solid #dec9b7;border-radius:18px;margin:14px 0;background:white"><h3>Chuyển khoản · 银行转账</h3>${paymentQrSvg(p.payload)}<p><strong>${fmt(p.amount)}</strong><br>${esc(p.bankLabel||'Ngân hàng')} · BIN ${esc(p.bankBin)}<br>Số tài khoản: ${esc(p.account)}<br>Chủ tài khoản: ${esc(p.accountName)}<br>Nội dung: ${esc(p.content)}</p><p class="sub">QR chứa đúng số tiền và tài khoản; nhân viên xác nhận khi đã kiểm tra tiền vào.<br>二维码含金额与收款账号，到账后请店员确认。</p><button class="secondary" data-action="payment-download">Tải QR PNG · 下载二维码</button><button class="secondary" data-action="payment-copy">Sao chép · 复制账号</button></div>`}
function paymentPng(o){const p=o.bankPayment;if(!p)throw Error('NO_BANK');const qr=new LotusQRCode(-1,1);qr.addData(p.payload);qr.make();const n=qr.getModuleCount(),pad=4,cell=7,c=document.createElement('canvas');c.width=(n+pad*2)*cell;c.height=c.width+165;const ctx=c.getContext('2d');if(!ctx)throw Error('NO_CANVAS');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#151515';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))ctx.fillRect((x+pad)*cell,(y+pad)*cell,cell,cell);ctx.font='bold 20px sans-serif';ctx.fillText(o.code+' · '+new Intl.NumberFormat('vi-VN').format(p.amount)+' đ',20,c.width+34);ctx.font='17px sans-serif';ctx.fillText(p.bankBin+' · '+p.account,20,c.width+67);ctx.fillText(p.accountName,20,c.width+99);ctx.fillText(p.content,20,c.width+131);const link=document.createElement('a');link.download='EchoCoffee_QR_'+o.code+'.png';link.href=c.toDataURL('image/png');document.body.appendChild(link);link.click();link.remove()}
async function copyBank(p){if(!p)return;const info=[p.bankBin,p.account,p.accountName,p.amount,p.content].join('\n');try{if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(info)}catch{try{const input=document.createElement('textarea');input.value=info;document.body.appendChild(input);input.select();if(!document.execCommand('copy'))throw Error('copy failed');input.remove()}catch{toast('Không sao chép được · 无法复制');return}}toast('Đã sao chép · 已复制')}
async function requestStaff(){const o=state.lastOrder;if(!o?.id||!state.orderToken||o.paymentStatus==='PAID')return;try{const r=await fetch('/api/orders/'+encodeURIComponent(o.id)+'/service',{method:'POST',headers:{'Content-Type':'application/json','x-order-token':state.orderToken},body:'{}',signal:AbortSignal.timeout(8000)});const v=await r.json();if(!r.ok)throw Error(v.message||'Không báo được');if(!v.ok)throw Error(v.message||'Không báo được');state.servicePending=true;state.lastOrder.serviceRequested=true;storage.set('lotus-qr-order:'+state.table,JSON.stringify({order:state.lastOrder,token:state.orderToken}));toast('Đã thông báo nhân viên đến bàn '+o.table+' / 已通知店员前来结账');render();return true}catch(e){toast(e.message);return false}}
function orderView(){if(state.demoPreview)return `<main class="section"><div class="result"><span class="status">${bi('demoBadge')}</span><h1 class="page-title" style="margin-top:17px">${bi('demoTitle')}</h1><p class="sub">${bi('demoDetail')}</p><button class="primary" data-view="cart">${bi('backCart')}</button></div></main>`;
 const o=state.lastOrder;if(!o)return `<main class="section"><h1 class="page-title">${bi('orders')}</h1><div class="empty">${bi('noOrder')}<p><button class="secondary" data-view="menu">${bi('browse')}</button></p></div></main>`;
 return `<main class="section"><div class="result"><span class="big-check">✓</span><h1 class="page-title" style="margin-top:14px">${bi('orderRecorded')}</h1><p class="sub">${bi('orderRecordedDetail')}</p><div class="sub">${bi('code')}</div><div class="result-code">${esc(o.code)}</div><span class="status">${tableText(o.table)}</span><div class="summary receipt-summary"><div class="sum-row"><span>${bi('subtotal')}</span><strong>${fmt(o.subtotal??o.total)}</strong></div>${o.voucherCode?`<div class="sum-row"><span>${bi('discount')} · ${esc(o.voucherCode)}</span><strong>−${fmt(o.discount||0)}</strong></div>`:''}<div class="sum-row total"><span>${bi('total')}</span><span>${fmt(o.total)}</span></div>${o.taxAmount?`<div class="sum-row"><span>${o.taxMode==='EXCLUSIVE'?'Thuế cộng thêm':'Thuế đã gồm'} · 税</span><strong>${fmt(o.taxAmount)}</strong></div>`:''}${o.refundedAmount?`<div class="sum-row"><span>Đã hoàn · 已退款</span><strong>−${fmt(o.refundedAmount)}</strong></div>`:''}<div class="sum-row"><span>${bi('payment')}</span><strong>${o.paymentStatus==='PAID'?bi('paid'):bi('unpaid')}</strong></div></div>${bankCard(o)}${o.paymentStatus==='PAID'||o.paymentPreference==='CASH'&&state.servicePending?`<div class="notice service-confirmation" role="status"><strong>Xin cảm ơn quý khách, nhân viên sẽ tới bàn phục vụ quý khách ngay bây giờ.</strong></div>`:''}${o.paymentStatus!=='PAID'&&!state.servicePending?`<button class="primary service-request" data-action="request-staff">Thông báo nhân viên / 通知店员</button><p class="sub">Nhân viên sẽ đến bàn ${esc(o.table)} để kiểm tra thanh toán. Khách không tự xác nhận đã thu.</p>`:''}<div class="notice">${o.paymentStatus==='PAID'?'Nhân viên đã xác nhận thanh toán · 店员已确认收款':bi('receiptNote')}</div><button class="primary" style="margin-top:16px" data-action="receipt" ${state.receiptBusy?'disabled':''}>${state.receiptBusy?bi('receiptPreparing'):bi('receiptDownload')}</button>${state.receiptImage?`<div class="receipt-image"><p class="sub">${bi('receiptPreview')}</p><img src="${state.receiptImage}" alt="${t('receipt')}"><p class="sub">${bi('receiptSave')}</p></div>`:''}<button class="secondary" style="width:100%;margin-top:12px" data-action="refresh" ${state.statusLoading?'disabled':''}>↻ ${bi('refresh')}</button><button class="secondary" style="width:100%;margin-top:10px" data-action="another">${bi('another')}</button></div></main>`}
function help(){return `<main class="section"><h1 class="page-title">${bi('guide')}</h1><div class="panel"><p>${bi('guide1')}</p><p>${bi('guide2')}</p><p>${bi('guide3')}</p><p>${bi('guide4')}</p><hr class="hr"><h3>${bi('service')}</h3><p class="sub">${bi('serviceText')}</p></div><div class="panel" style="margin-top:13px"><strong>${bi('selectTable')}</strong><p class="sub">${bi('tableWarn')}</p><button class="secondary" data-action="table">${bi('selectAgain')}</button></div></main>`}
function menuPrice(p,mods){let n=mods.size==='大'?p.largePrice:p.price;for(const g of p.modifiers||[])for(const code of mods.options?.[g.code]||[])n+=Number(g.options.find(x=>x.code===code)?.priceDelta||0);return n}
function optionLabels(mods,product){return Object.entries(mods.options||{}).flatMap(([group,chosen])=>(Array.isArray(chosen)?chosen:[]).map(x=>typeof x==='string'?(product?.modifiers||[]).find(g=>g.code===group)?.options.find(o=>o.code===x)?.name||x:x?.name)).filter(Boolean).join(' · ')}
function modal(){if(!state.modal)return '';const m=state.modal,p=m.product,optsSize=p.size?['中','大']:['中'],optsSpice=p.spicy?['不辣','小','中','大']:['中'];const sizeLabel={'中':'regular','大':'large'},spiceLabel={'不辣':'none',小:'mild',中:'medium',大:'hot'};return `<div class="modal-backdrop" data-backdrop="1"><section class="sheet" role="dialog" aria-modal="true" aria-label="${t('choose')}"><div class="sheet-top"><h2>${names(p)}</h2><button class="iconbtn" data-action="close" aria-label="${t('close')}">×</button></div><div class="sheet-body">${productImage(p)}<div class="field"><label>${bi('size')}</label><div class="option-group">${optsSize.map(v=>`<button class="option ${m.mods.size===v?'selected':''}" data-opt="size" data-val="${v}" aria-pressed="${m.mods.size===v}">${bi(sizeLabel[v])}${p.price!==p.largePrice?' · '+fmt(v==='大'?p.largePrice:p.price):''}</button>`).join('')}</div></div>${p.spicy?`<div class="field"><label>${bi('spice')}</label><div class="option-group">${optsSpice.map(v=>`<button class="option ${m.mods.spice===v?'selected':''}" data-opt="spice" data-val="${v}" aria-pressed="${m.mods.spice===v}">${bi(spiceLabel[v])}</button>`).join('')}</div></div>`:''}${(p.modifiers||[]).map(g=>`<div class="field"><label>${esc(g.code==='DRINK_TOPPING'?'Topping / 配料':g.code==='SAUCE_FRIED_CHICKEN'?'Chọn sốt / 选择酱汁':g.code==='COMBO_RICE_MAIN'?'Chọn cơm / 选择主食':'Chọn trà / 选择茶饮')} ${g.min?'*':''}</label><div class="option-group">${g.options.map(o=>`<button class="option ${(m.mods.options?.[g.code]||[]).includes(o.code)?'selected':''}" data-mod-group="${esc(g.code)}" data-mod-code="${esc(o.code)}" aria-pressed="${(m.mods.options?.[g.code]||[]).includes(o.code)}">${esc(o.name)} / ${esc(o.nameCn)}${o.priceDelta?' +'+fmt(o.priceDelta):''}</button>`).join('')}</div></div>`).join('')}<div class="field"><label for="item-note">${bi('note')}</label><textarea id="item-note" maxlength="100" rows="2" placeholder="${esc(translations.vi.notePlaceholder)}">${esc(m.mods.note)}</textarea></div><div class="sheet-quantity"><strong>${bi('qty')}</strong><div class="qty"><button data-action="mod-minus" aria-label="Giảm / 减少">−</button><span id="modal-qty">${m.qty}</span><button data-action="mod-plus" aria-label="Tăng / 增加">+</button></div></div></div><div class="sheet-foot"><button class="primary" data-action="modal-save">${m.editIndex===null?bi('add'):bi('save')} · <span id="modal-total">${fmt(menuPrice(p,m.mods)*m.qty)}</span></button></div></section></div>`}
function picker(){if(!state.tablePicker)return '';const options=Array.from({length:state.catalog.store.tableCount||99},(_,i)=>'T'+String(i+1).padStart(2,'0'));return `<div class="modal-backdrop"><section class="sheet" role="dialog" aria-modal="true" aria-label="${t('selectTable')}"><div class="sheet-top"><h2>${bi('selectTable')}</h2>${state.table?`<button class="iconbtn" data-action="close-table" aria-label="${t('close')}">×</button>`:''}</div><div class="sheet-body"><p class="sub">${bi('tableWarn')}</p>${state.badTable?`<div class="notice red">${bi('errorTable')}</div>`:''}<div class="table-select">${options.map(v=>`<button data-pick="${v}" class="${(state.pendingTable||state.table)===v?'selected':''}">${v}</button>`).join('')}<button data-pick="TAKEAWAY" class="${(state.pendingTable||state.table)==='TAKEAWAY'?'selected':''}" style="grid-column:span 2">${bi('takeaway')}</button></div></div><div class="sheet-foot"><button class="primary" data-action="confirm-table" ${!(state.pendingTable||state.table)?'disabled':''}>${bi('confirmTable')}</button></div></section></div>`}
function render(){const el=$('#app');el.innerHTML=`<div class="app ${state.view==='cart'&&count()?'cart-active':''}">${header()}${state.view==='menu'?menu():state.view==='cart'?cart():state.view==='orders'?orderView():state.view==='member'?memberView():help()}${state.view==='menu'&&count()?`<div class="dock"><button data-view="cart"><span><span class="count">${count()}</span>${bi('seeCart')}</span><strong>${fmt(total())} →</strong></button></div>`:state.view==='cart'&&count()?`<div class="dock"><button class="cart-submit ${isReady()?'':'disabled-submission'}" data-action="submit" ${state.submitting?'disabled':''}><span class="cart-submit-label">${state.submitting?'Đang xác nhận… / 正在确认…':isReady()?'Xác nhận gọi món / 确认点餐':'Xem trước (DEMO) / 演示预览'}</span><strong>${fmt(discountedTotal())} →</strong></button></div>`:''}${footer()}</div>${modal()}${picker()}`;document.documentElement.lang='vi';document.body.style.overflow=state.modal||state.tablePicker?'hidden':'';}
async function refreshMember(){try{const r=await fetch('/api/member/me',{credentials:'same-origin',cache:'no-store'});const v=await r.json();if(v.ok){state.member=v.member;if(!v.member)state.loyaltyTransactions=[]}}catch{}if(state.view==='member'||state.view==='cart')render()}
async function refreshLoyalty(){if(!state.member)return;try{const r=await fetch('/api/member/loyalty',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(7500)});const v=await r.json();if(r.ok&&v.ok){state.member=v.member;state.loyaltyTransactions=v.transactions}}catch{}if(state.view==='member')render()}
async function refreshVouchers(background=false){const before=JSON.stringify(state.vouchers);try{const r=await fetch('/api/vouchers',{credentials:'same-origin',cache:'no-store'});const v=await r.json();if(v.ok&&Array.isArray(v.vouchers))state.vouchers=v.vouchers}catch{}if(state.view==='cart'&&(!background||before!==JSON.stringify(state.vouchers)&&!document.activeElement?.closest?.('form')))render()}
function voucherPayload(){return {table:state.table,items:state.cart.map(x=>({productId:x.productId,qty:x.qty,mods:x.mods})),note:state.orderNote,voucherCode:state.voucherCode}}
async function applyVoucher(selectedCode=null){if(!state.cart.length||state.voucherBusy)return;const input=$('#voucher-input');if(selectedCode)state.voucherCode=selectedCode;else if(input)state.voucherCode=input.value.trim().toUpperCase();if(!state.voucherCode){clearVoucher();render();return}state.voucherBusy=true;try{const r=await fetch('/api/vouchers/validate',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(voucherPayload()),signal:AbortSignal.timeout(8500)});const v=await r.json();if(!r.ok||!v.ok){state.appliedVoucher=null;toast((v.message||translations.vi.voucherError)+' / '+(v.messageCn||translations.zh.voucherError));if(v.code==='MEMBER_REQUIRED')state.memberReturnView='cart';return}state.appliedVoucher=v;rotateIdempotency();toast(t('voucherApplied'))}catch{state.appliedVoucher=null;toast(t('voucherError'))}finally{state.voucherBusy=false;render()}}
async function sendAuth(form){if(state.authBusy)return;const fd=new FormData(form),mode=state.authMode;state.authBusy=true;const data={phone:String(fd.get('phone')||'')};if(!/^0\d{9,10}$/.test(data.phone)){toast('Số điện thoại phải có 10 hoặc 11 số / 手机号须为10或11位');state.authBusy=false;return}if(mode==='register')data.name=String(fd.get('name')||'');else data.password=String(fd.get('password')||'');try{const r=await fetch('/api/member/'+mode,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(15000)});const v=await r.json();if(!r.ok||!v.ok){toast((v.message||translations.vi.accountError)+' / '+(v.messageCn||translations.zh.accountError));return}state.member=v.member;state.loyaltyTransactions=[];clearVoucher();rotateIdempotency();state.view=state.memberReturnView==='cart'?'cart':'member';state.memberReturnView='member';await refreshVouchers();if(state.view==='member')await refreshLoyalty()}catch{toast(t('accountError'))}finally{state.authBusy=false;render()}}
async function changePassword(form){const fd=new FormData(form);try{const r=await fetch('/api/member/password',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:fd.get('currentPassword'),newPassword:fd.get('newPassword')}),signal:AbortSignal.timeout(15000)});const v=await r.json();if(!r.ok)throw Error(v.message||'Không đổi được mật khẩu');state.member=null;state.loyaltyTransactions=[];state.authMode='login';render();toast('Đã đổi mật khẩu. Đăng nhập lại / 密码已修改，请重新登录')}catch(e){toast(e.message)}}
async function logoutMember(){if(state.authBusy)return;state.authBusy=true;try{const r=await fetch('/api/member/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error('logout failed');state.member=null;state.loyaltyTransactions=[];state.authMode='login';clearVoucher();rotateIdempotency();await refreshVouchers()}catch{toast(t('accountError'))}finally{state.authBusy=false;render()}}
// Receipt is generated ONLY from the server-acknowledged order snapshot, never cart prices.
function makeReceiptPng(o){
 const canvas=document.createElement('canvas'),width=900,pad=56;
 canvas.width=width;const rows=[];
 const add=(text,size=25,bold=false,align='left',color='#35271f')=>rows.push({text:String(text),size,bold,align,color});
 const duo=(vi,zh,vsize=25,zsize=21)=>{add(vi,vsize,true);add(zh,zsize,false,'left','#75685a')};
 const money=n=>fmt(Number(n)||0);
 add(state.catalog.store.name||'Lotus POS',38,true,'center','#762b26');add(state.catalog.store.nameCn||'',31,true,'center','#762b26');add('PHIẾU GỌI MÓN',29,true,'center');add('点餐确认单',25,true,'center');
 add(o.paymentStatus==='PAID'?'ĐÃ THANH TOÁN':'CHƯA THANH TOÁN',25,true,'center','#a14b26');
 add(o.paymentStatus==='PAID'?'已付款':'未付款',23,true,'center','#a14b26');
 add('───────────────────────────────',21);
 duo('Mã đơn','订单号');add(o.code,29,true);
 duo('Bàn','桌号');add(o.table==='TAKEAWAY'?'Mang đi':o.table,27,true);if(o.table==='TAKEAWAY')add('打包',23);
 duo('Thời gian','时间');add(new Date(o.createdAt).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}),24);
 if(o.memberName){duo('Hội viên','会员');add(o.memberName,24)}
 add('───────────────────────────────',21);
 duo('MÓN ĂN','菜品',29,24);
 for(const it of o.items){
  add(it.name,28,true);add(it.nameCn||it.name,23,false,'left','#75685a');
  const sizeVi=it.mods?.size==='大'?'Lớn':'Vừa',sizeZh=it.mods?.size==='大'?'大份':'中份';
  const spiceVi=it.mods?.spice==='不辣'?'Không cay':it.mods?.spice==='小'?'Ít cay':it.mods?.spice==='大'?'Cay nhiều':'Cay vừa';
  const spiceZh=it.mods?.spice==='不辣'?'不辣':it.mods?.spice==='小'?'小辣':it.mods?.spice==='大'?'大辣':'中辣';
  add(sizeVi+' · '+spiceVi,21);add(sizeZh+' · '+spiceZh,20,false,'left','#75685a');
  if(it.mods?.note){add('Ghi chú: '+it.mods.note,20);add('备注: '+it.mods.note,19,false,'left','#75685a')}
  add('Số lượng '+it.qty+' × '+money(it.price),22,true);
  add('数量 '+it.qty+' × '+money(it.price),20,false,'left','#75685a');
  add(money(it.price*it.qty),27,true,'right','#762b26');add(' ',10);
 }
 add('───────────────────────────────',21);
 duo('Tạm tính: '+money(o.subtotal??o.total),'小计: '+money(o.subtotal??o.total),25,22);
 if(o.voucherCode)duo('Ưu đãi '+o.voucherCode+': −'+money(o.discount),'优惠 '+o.voucherCode+': −'+money(o.discount),25,22);
 if(o.taxAmount)duo((o.taxMode==='EXCLUSIVE'?'Thuế cộng thêm: ':'Thuế đã gồm: ')+money(o.taxAmount),'税额: '+money(o.taxAmount),25,22);
 add('TỔNG CỘNG: '+money(o.total),34,true,'left','#762b26');
 add('合计: '+money(o.total),29,true,'left','#762b26');
 if(o.refundedAmount)duo('Đã hoàn: −'+money(o.refundedAmount),'已退款: −'+money(o.refundedAmount),24,21);
 duo(o.paymentStatus==='PAID'?'Nhân viên đã xác nhận thanh toán':o.bankPayment?'Có QR thanh toán riêng trên màn hình':'Thanh toán tiền mặt với nhân viên',o.paymentStatus==='PAID'?'店员已确认付款':o.bankPayment?'屏幕另有转账二维码':'请向店员付现金',24,21);
 if(o.note)duo('Ghi chú: '+o.note,'备注: '+o.note,21,19);
 add('───────────────────────────────',21);
 add('Phiếu tạm tính, không phải hóa đơn VAT',21,false,'center');
 add('仅供核对，非税务发票或付款证明',20,false,'center');
 const ctx=canvas.getContext('2d');if(!ctx)throw Error('Canvas unavailable');const wrapped=[];
 for(const row of rows){
  ctx.font=`${row.bold?'700':'400'} ${row.size}px system-ui,"Noto Sans",sans-serif`;
  if(row.text===' '){wrapped.push(row);continue}
  let line='';for(const ch of row.text){if(ctx.measureText(line+ch).width>width-2*pad&&line){wrapped.push({...row,text:line});line=ch}else line+=ch}
  if(line)wrapped.push({...row,text:line});
 }
 const height=row=>Math.max(24,Math.round(row.size*1.48));
 canvas.height=2*pad+wrapped.reduce((sum,r)=>sum+height(r),0);
 ctx.fillStyle='#fffdf8';ctx.fillRect(0,0,width,canvas.height);
 let y=pad;for(const row of wrapped){ctx.font=`${row.bold?'700':'400'} ${row.size}px system-ui,"Noto Sans",sans-serif`;
  ctx.textBaseline='top';ctx.textAlign=row.align;ctx.fillStyle=row.color;
  ctx.fillText(row.text,row.align==='center'?width/2:row.align==='right'?width-pad:pad,y);y+=height(row)}
 return canvas.toDataURL('image/png');
}
async function receipt(){if(!state.lastOrder?.id||state.demoPreview||state.receiptBusy)return;state.receiptBusy=true;render();try{await refreshOrder();const o=state.lastOrder;if(!o?.id)throw Error('Missing confirmed order');const image=makeReceiptPng(o);if(!image.startsWith('data:image/png'))throw Error('No PNG');state.receiptImage=image;const a=document.createElement('a');a.href=image;a.download='EchoCoffee_DonHang_'+o.code.replace(/[^A-Za-z0-9_-]/g,'')+'.png';document.body.appendChild(a);a.click();a.remove()}catch{toast(t('receiptError'))}finally{state.receiptBusy=false;render()}}
function refreshProductList(){const container=$('#product-list');if(container)container.innerHTML=productList()}
function showModal(p,index=null){if(state.uncertain){toast(t('uncertainEdit'));return}state.modal={product:p,editIndex:index,qty:index===null?1:state.cart[index].qty,mods:index===null?{size:'中',spice:'中',note:'',options:{}}:{...state.cart[index].mods,options:{...(state.cart[index].mods.options||{})}}};render()}
function updateModal(){const m=state.modal;if(!m)return;const q=$('#modal-qty'),price=$('#modal-total');if(q)q.textContent=m.qty;if(price)price.textContent=fmt(menuPrice(m.product,m.mods)*m.qty);document.querySelectorAll('[data-opt]').forEach(b=>{const selected=m.mods[b.dataset.opt]===b.dataset.val;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
function setTable(table){if(!validTable(table)||table!=='TAKEAWAY'&&Number(table.slice(1))>(state.catalog.store.tableCount||99))return;const old=state.table;state.table=table;state.badTable=false;state.tablePicker=false;state.pendingTable='';storage.set('lotus-qr-table',table);loadCart();state.demoPreview=false;state.uncertain=false;state.modal=null;clearVoucher();state.receiptImage='';if(old!==table){state.lastOrder=null;state.orderToken=null;state.servicePending=false;restoreOrder()}try{const u=new URL(location.href);u.searchParams.set('table',table);history.replaceState(null,'',u)}catch{}render()}
function restoreOrder(){try{const o=JSON.parse(storage.get('lotus-qr-order:'+state.table)||'null');if(o?.order?.id&&o.token)state.lastOrder=o.order,state.orderToken=o.token,state.servicePending=!!o.order.serviceRequested}catch{}}
async function refreshHealth(background=false){if(catalogRefreshing)return;catalogRefreshing=true;let cartRepriced=false,categoryChanged=false,storeChanged=false;try{const response=await fetch('/api/catalog',{cache:'no-store',signal:AbortSignal.timeout(7500)});if(!response.ok)throw Error('API unavailable');const data=await response.json();if(!data.ok||!Array.isArray(data.catalog.products))throw Error('Bad catalog');categoryChanged=state.catalog.products.map(p=>p.category).join('|')!==data.catalog.products.map(p=>p.category).join('|');storeChanged=JSON.stringify(state.catalog.store)!==JSON.stringify(data.catalog.store);state.catalog=data.catalog;if(state.table&&state.table!=='TAKEAWAY'&&Number(state.table.slice(1))>(state.catalog.store.tableCount||99)){state.badTable=true;state.tablePicker=true}if(!state.submitting&&!state.uncertain){let changed=false;for(const x of state.cart){const p=getProduct(x.productId);if(p){const price=menuPrice(p,x.mods);if(x.price!==price){x.price=price;changed=true}}}if(changed){cartRepriced=true;clearVoucher();rotateIdempotency();saveCart()}}state.accepting=data.acceptingOrders===true;state.serverOnline=true;if(!background){refreshMember();refreshVouchers()}}catch{state.serverOnline=false;state.accepting=false;try{const response=await fetch('/catalog.json',{cache:'no-store'});if(response.ok)state.catalog=await response.json()}catch{}}finally{catalogRefreshing=false}if(background){if(state.view==='menu'){const h=$('#menu-hero'),b=$('#menu-connect');if(h)h.innerHTML=hero();if(b)b.innerHTML=banner();refreshProductList()}else if(state.view==='cart'){const b=$('#cart-connect');if(b)b.innerHTML=banner();const submit=$('.cart-submit');if(submit){submit.classList.toggle('disabled-submission',!isReady());const caption=submit.querySelector('span');if(caption)caption.textContent=state.submitting?t('sending'):isReady()?t('submit'):t('demoSubmit')}}}else{saveCart();render()}if(background&&((cartRepriced&&state.view==='cart')||(categoryChanged&&state.view==='menu')||storeChanged)&&!document.activeElement?.closest?.('form'))render();if(background&&state.view==='cart')refreshVouchers(true)}
async function refreshOrder(){if(!state.lastOrder?.id||!state.orderToken||state.statusLoading)return;state.statusLoading=true;try{const response=await fetch('/api/orders/'+encodeURIComponent(state.lastOrder.id),{headers:{'x-order-token':state.orderToken},cache:'no-store',signal:AbortSignal.timeout(7000)});if(!response.ok)throw Error('STATUS_UNAVAILABLE');const result=await response.json();state.lastOrder=result.order;state.servicePending=!!result.order.serviceRequested;storage.set('lotus-qr-order:'+state.table,JSON.stringify({order:state.lastOrder,token:state.orderToken}));}catch{toast(t('orderLost'))}finally{state.statusLoading=false;if(state.view==='orders')render()}}
function idempotencyKey(){let key=storage.get(cartKey()+':request');if(!key){key='qr_'+(crypto.randomUUID?crypto.randomUUID().replaceAll('-',''):Math.random().toString(36).slice(2)+Date.now().toString(36));storage.set(cartKey()+':request',key)}return key}
function rotateIdempotency(){storage.set(cartKey()+':request','')}
async function submit(){if(state.submitting||!state.cart.length)return;if(!state.table){state.tablePicker=true;render();return}if(!isReady()){state.demoPreview=true;state.view='orders';render();return}state.submitting=true;render();let responseStatus=0,errorCode='';try{const response=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({table:state.table,items:state.cart.map(x=>({productId:x.productId,qty:x.qty,mods:x.mods})),note:state.orderNote,voucherCode:state.appliedVoucher?.voucher.code||'',paymentPreference:state.paymentChoice,idempotencyKey:idempotencyKey()}),signal:AbortSignal.timeout(11000)});responseStatus=response.status;const data=await response.json();errorCode=data.code||'';if(!response.ok||!data.ok||!data.order?.id||!data.orderToken){throw Error(data.message&&data.messageCn?data.message+' / '+data.messageCn:data.message||'NO_ACK')}state.lastOrder=data.order;state.servicePending=!!data.order.serviceRequested;state.orderToken=data.orderToken;storage.set('lotus-qr-order:'+state.table,JSON.stringify({order:data.order,token:data.orderToken}));state.cart=[];state.orderNote='';clearVoucher();state.receiptImage='';saveCart();rotateIdempotency();state.demoPreview=false;state.uncertain=false;state.view='orders';render();if(data.order.paymentPreference==='CASH'&&!state.servicePending)await requestStaff();}catch(e){const voucherRejected=['INVALID_VOUCHER','VOUCHER_UNAVAILABLE','VOUCHER_MEMBER_LIMIT','VOUCHER_FULL','VOUCHER_MIN','MEMBER_REQUIRED','PHONE_NOT_VERIFIED'].includes(errorCode);const stockRejected=['OUT_OF_STOCK','INGREDIENT_OUT_OF_STOCK'].includes(errorCode);state.uncertain=responseStatus===0||(responseStatus===409&&!voucherRejected&&!stockRejected)||responseStatus>=500;if(voucherRejected){clearVoucher();rotateIdempotency()}if(stockRejected)rotateIdempotency();console.warn('Order not acknowledged',errorCode||e.message);toast(state.uncertain?t('orderFail'):(e.message||t('error')));await refreshHealth()}finally{state.submitting=false;render()}}
function changeQty(index,delta){if(state.uncertain){toast(t('uncertainEdit'));return}const x=state.cart[index];if(!x)return;const next=x.qty+delta;if(next>30){toast(t('error'));return}if(next<1)state.cart.splice(index,1);else x.qty=next;rotateIdempotency();clearVoucher();saveCart();render()}
function saveModal(){if(state.uncertain){toast(t('uncertainEdit'));return}const m=state.modal;if(!m)return;const note=$('#item-note');if(note)m.mods.note=note.value.trim().slice(0,100);for(const g of m.product.modifiers||[]){const n=m.mods.options?.[g.code]?.length||0;if(n<g.min||n>g.max){toast('Chọn đủ tùy chọn cho '+g.code+' / 请完成必选项');return}}const price=menuPrice(m.product,m.mods);const item={key:getCartKey(m.product.id,m.mods),productId:String(m.product.id),qty:m.qty,price,mods:{...m.mods}};rotateIdempotency();clearVoucher();if(m.editIndex!==null)state.cart.splice(m.editIndex,1);const current=state.cart.find(x=>x.key===item.key);if(current){current.qty=Math.min(30,current.qty+item.qty)}else state.cart.push(item);state.modal=null;saveCart();render();toast(t('saved'))}
function dispatch(button){if(button.dataset.view){state.view=button.dataset.view;state.modal=null;state.demoPreview=state.demoPreview&&state.view==='orders';render();window.scrollTo(0,0);if(state.view==='orders'&&!state.demoPreview)refreshOrder();if(state.view==='member')refreshLoyalty();return}
 if(button.dataset.paymentChoice){state.paymentChoice=button.dataset.paymentChoice;rotateIdempotency();render();return}
 if(button.dataset.authMode){state.authMode=button.dataset.authMode;render();return}
 if(button.dataset.offer){applyVoucher(button.dataset.offer);return}
 if(button.dataset.cat){state.category=button.dataset.cat;render();return}
 if(button.dataset.add){const p=getProduct(button.dataset.add);if(p?.available)showModal(p);return}
 if(button.dataset.qty!==undefined){changeQty(Number(button.dataset.qty),Number(button.dataset.delta));return}
 if(button.dataset.remove!==undefined){if(state.uncertain){toast(t('uncertainEdit'));return}state.cart.splice(Number(button.dataset.remove),1);rotateIdempotency();clearVoucher();saveCart();render();return}
 if(button.dataset.edit!==undefined){const ix=Number(button.dataset.edit);const p=getProduct(state.cart[ix]?.productId);if(p)showModal(p,ix);return}
 if(button.dataset.modGroup&&state.modal){const m=state.modal,group=m.product.modifiers?.find(g=>g.code===button.dataset.modGroup);if(!group)return;const note=$('#item-note');if(note)m.mods.note=note.value;const chosen=[...(m.mods.options?.[group.code]||[])],code=button.dataset.modCode,ix=chosen.indexOf(code);if(ix>=0)chosen.splice(ix,1);else if(group.max===1)chosen.splice(0,chosen.length,code);else if(chosen.length<group.max)chosen.push(code);m.mods.options={...m.mods.options,[group.code]:chosen};render();return}
 if(button.dataset.opt&&state.modal){const m=state.modal,note=$('#item-note');if(note)m.mods.note=note.value; m.mods[button.dataset.opt]=button.dataset.val;updateModal();return}
 if(button.dataset.pick){state.pendingTable=button.dataset.pick;state.tablePicker=true;render();return}
 const action=button.dataset.action;
 if(action==='member-from-cart'){state.memberReturnView='cart';state.view='member';state.authMode='login';render();refreshLoyalty()}
 else if(action==='refresh-loyalty')refreshLoyalty();
 else if(action==='apply-voucher')applyVoucher();
 else if(action==='remove-voucher'){clearVoucher();rotateIdempotency();render()}
 else if(action==='logout')logoutMember();
 else if(action==='receipt')receipt();
 else if(action==='payment-download'){try{paymentPng(state.lastOrder)}catch{toast('Không tạo được ảnh QR · 无法生成图片')}}
 else if(action==='payment-copy')copyBank(state.lastOrder?.bankPayment);
 else if(action==='request-staff')requestStaff();
 else if(action==='table'){state.tablePicker=true;render()}
 else if(action==='close-table'){state.tablePicker=false;render()}
 else if(action==='confirm-table'){setTable(state.pendingTable||state.table)}
 else if(action==='close'){state.modal=null;render()}
 else if(action==='mod-minus'){state.modal.qty=Math.max(1,state.modal.qty-1);updateModal()}
 else if(action==='mod-plus'){state.modal.qty=Math.min(30,state.modal.qty+1);updateModal()}
 else if(action==='modal-save')saveModal();
 else if(action==='submit')submit();
 else if(action==='refresh')refreshOrder();
 else if(action==='another'){state.demoPreview=false;state.view='menu';render()}
 }
document.addEventListener('submit',event=>{if(event.target.id==='member-form'){event.preventDefault();sendAuth(event.target)}else if(event.target.id==='change-password-form'){event.preventDefault();changePassword(event.target)}});
document.addEventListener('click',event=>{const b=event.target.closest('button');if(b){dispatch(b);return}if(event.target.matches('[data-backdrop]')){state.modal=null;render()}});
document.addEventListener('input',event=>{if(event.target.id==='voucher-input'){state.voucherCode=event.target.value.toUpperCase();if(state.appliedVoucher&&state.appliedVoucher.voucher.code!==state.voucherCode.trim()){state.appliedVoucher=null;rotateIdempotency()}}else if(event.target.id==='search'){state.search=event.target.value;refreshProductList()}else if(event.target.id==='order-note'){if(state.uncertain){event.target.value=state.orderNote;toast(t('uncertainEdit'));return}state.orderNote=event.target.value.slice(0,300);rotateIdempotency();saveCart()}else if(event.target.id==='item-note'&&state.modal){state.modal.mods.note=event.target.value.slice(0,100)}});
window.addEventListener('online',()=>refreshHealth(true));window.addEventListener('offline',()=>{state.serverOnline=false;state.accepting=false;refreshHealth(true)});document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshHealth(true);if(state.view==='orders')refreshOrder()}});
